html:
{# =========================================================
   MATERIAL REQUEST PRINT FORMAT
   STYLE: Similar to RFQ clean design
   LOGIC:
   - Purchase => show signatures + stamp
   - Material Transfer => hide signatures
========================================================= #}

{% macro _val(v, fallback="-") %}{{ v if v not in (None, "", []) else fallback }}{% endmacro %}

{# -------------------------
   BASIC VALUES
-------------------------- #}
{% set mr_date = doc.transaction_date or doc.schedule_date or "" %}
{% set required_date = doc.schedule_date or "" %}
{% set purpose = doc.material_request_type or "" %}
{% set workflow_state = doc.workflow_state or doc.status or "-" %}
{% set owner_email = doc.owner or "-" %}
{% set full_name = doc.full_name or frappe.db.get_value("User", doc.owner, "full_name") or doc.owner %}
{% set department = doc.department or "-" %}
{% set hod_approver = doc.hod_approver or doc.custom_hod_approver or "-" %}

{# -------------------------
   SIGNATURE LOGIC
-------------------------- #}
{% set prepared_by_user = doc.owner %}
{% set prepared_by_name = frappe.db.get_value("User", prepared_by_user, "full_name") or prepared_by_user %}
{% set approved_by_name = "Jibril Dahir Hersi" %}

{% set prepared_sig = "" %}
{% if prepared_by_user == "ayaanle@shaafi.com" %}
    {% set prepared_sig = frappe.db.get_value("File", {"file_name": "Ayanle Signature.PNG"}, "file_url") %}
{% elif prepared_by_user == "pharmacy@shaafihospital.com" %}
    {% set prepared_sig = frappe.db.get_value("File", {"file_name": "Cabaas Signature.PNG"}, "file_url") %}
{% endif %}

{% set approved_sig = frappe.db.get_value("File", {"file_name": "Jibril Signature.PNG"}, "file_url") %}
{% set common_stamp = frappe.db.get_value("File", {"file_name": "Proc Stamp.PNG"}, "file_url") %}

<style>
  .mr-wrap{
    font-family: "Segoe UI", Tahoma, Arial, sans-serif;
    color:#111;
    font-size: 12px;
    line-height: 1.35;
  }

  .mr-wrap *{
    box-sizing: border-box;
  }

  .mr-title{
    text-align:left;
    margin-top: 6px;
  }

  .mr-title h2{
    margin:0;
    font-size: 18px;
    font-weight: 600;
    color:#000;
  }

  .mr-title .ref{
    margin-top: 2px;
    font-size: 12px;
    color:#000;
  }

  .mr-divider{
    border:0;
    border-top:1px solid #222;
    margin: 8px 0 12px 0;
    opacity: .85;
  }

  .mr-info{
    width:100%;
    border-collapse: collapse;
    margin-bottom: 16px;
  }

  .mr-info td{
    padding: 3px 6px;
    vertical-align: top;
    font-size: 12px;
  }

  .mr-info .lbl{
    font-weight: 700;
    width: 110px;
    white-space: nowrap;
    color:#000;
  }

  .mr-info .val{
    width: 210px;
    color:#000;
  }

  .mr-info .lbl-r{
    font-weight: 700;
    width: 130px;
    white-space: nowrap;
    padding-left: 26px;
    color:#000;
  }

  .mr-card{
    margin-top: 10px;
    border: 1px solid #d9dee7;
    border-radius: 8px;
    padding: 10px 12px 12px 12px;
    background: #fff;
  }

  .mr-card-title{
    font-weight: 700;
    font-size: 12px;
    margin-bottom: 8px;
    color:#000;
  }

  .mr-items{
    width:100%;
    border-collapse: collapse;
    table-layout: fixed;
    font-size: 11.5px;
  }

  .mr-items th,
  .mr-items td{
    padding: 6px 7px;
    border-bottom: 1px solid #e7ebf0;
    vertical-align: top;
    word-break: break-word;
  }

  .mr-items th{
    text-align: left;
    font-weight: 700;
    color:#000;
    background: #fff;
  }

  .mr-items tr:last-child td{
    border-bottom: 0;
  }

  .c-center{ text-align:center; }
  .c-right{ text-align:right; white-space: nowrap; }

  .col-sr{ width:38px; }
  .col-code{ width:170px; }
  .col-date{ width:110px; }
  .col-qty{ width:85px; }
  .col-wh{ width:150px; }

  .mr-terms{
    min-height: 90px;
    white-space: pre-wrap;
    line-height: 1.45;
    font-size: 11.5px;
  }

  .mr-sign-row{
    margin-top: 40px;
    display: table;
    width:100%;
    table-layout: fixed;
  }

  .mr-sign-box,
  .mr-stamp-box{
    display: table-cell;
    text-align: center;
    vertical-align: bottom;
  }

  .mr-sign-box{ width: 36%; }
  .mr-stamp-box{ width: 28%; }

  .sign-display{
    height: 82px;
    display:flex;
    align-items:flex-end;
    justify-content:center;
  }

  .sign-img{
    max-height: 72px;
    max-width: 190px;
    object-fit: contain;
  }

  .stamp-display{
    height: 120px;
    display:flex;
    align-items:center;
    justify-content:center;
  }

  .stamp-img{
    max-height: 118px;
    max-width: 118px;
    object-fit: contain;
    opacity: 0.9;
  }

  .sign-line{
    margin-top: 8px;
    border-top: 1px dashed #333;
    padding-top: 6px;
    font-weight: 700;
    font-size: 12px;
    color:#000;
  }

  .sign-name{
    margin-top: 4px;
    font-size: 12px;
    font-weight: 700;
    color:#000;
  }

  .sign-note{
    margin-top: 2px;
    font-size: 11px;
    color:#000;
  }

  .mr-contact{
    margin-top: 14px;
    border-top: 1px solid #e3e7ed;
    padding-top: 8px;
    display:flex;
    justify-content: space-between;
    gap: 12px;
    font-size: 10.8px;
    color:#000;
  }

  .mr-contact b{
    color:#000;
  }

  @media print{
    .mr-wrap{ margin:0; }
  }
</style>

<div class="mr-wrap">
  {{ letter_head }}

  <div class="mr-title">
    <h2>Material Request</h2>
    <div class="ref">{{ doc.name }}</div>
  </div>

  <hr class="mr-divider">

  <table class="mr-info">
    <tr>
      <td class="lbl">Workflow State:</td>
      <td class="val">{{ _val(workflow_state) }}</td>

      <td class="lbl-r"></td>
      <td class="val"></td>
    </tr>

    <tr>
      <td class="lbl">User:</td>
      <td class="val">{{ _val(owner_email) }}</td>

      <td class="lbl-r">Transaction Date:</td>
      <td class="val">{{ _val(mr_date) }}</td>
    </tr>

    <tr>
      <td class="lbl">Full Name:</td>
      <td class="val">{{ _val(full_name) }}</td>

      <td class="lbl-r">Required By:</td>
      <td class="val">{{ _val(required_date) }}</td>
    </tr>

    <tr>
      <td class="lbl">Department:</td>
      <td class="val">{{ _val(department) }}</td>

      <td class="lbl-r"></td>
      <td class="val"></td>
    </tr>

    <tr>
      <td class="lbl">HOD Approver:</td>
      <td class="val">{{ _val(hod_approver) }}</td>

      <td class="lbl-r"></td>
      <td class="val"></td>
    </tr>

    <tr>
      <td class="lbl">Purpose:</td>
      <td class="val">{{ _val(purpose) }}</td>

      <td class="lbl-r"></td>
      <td class="val"></td>
    </tr>
  </table>

  <div class="mr-card">
    <div class="mr-card-title">Items</div>

    <table class="mr-items">
      <thead>
        <tr>
          <th class="col-sr c-center">Sr</th>
          <th class="col-code">Item Code</th>
          <th class="col-date">Required By</th>
          <th>Description</th>
          <th class="col-qty c-right">Quantity</th>
          <th class="col-wh">Target Warehouse</th>
        </tr>
      </thead>
      <tbody>
        {% for row in (doc.items or []) %}
        <tr>
          <td class="c-center">{{ loop.index }}</td>
          <td>{{ row.item_code or "-" }}</td>
          <td>{{ row.schedule_date or doc.schedule_date or "-" }}</td>
          <td>{{ row.description or row.item_name or row.item_code or "-" }}</td>
          <td class="c-right">
            {{ row.qty or row.stock_qty or 0 }}
            {% if row.uom %} {{ row.uom }}{% endif %}
          </td>
          <td>{{ row.warehouse or "-" }}</td>
        </tr>
        {% endfor %}
      </tbody>
    </table>
  </div>

<!--  <div class="mr-card">-->
<!--    <div class="mr-card-title">Terms & Conditions</div>-->
<!--    <div class="mr-terms">-->
<!--- Delivery: ________________-->
<!--- Payment Terms: __________________-->
<!--- Validity: __________________-->
<!--- Notes: __________________-->
<!--    </div>-->
<!--  </div>-->

  {% if doc.material_request_type == "Purchase" %}
  <div class="mr-sign-row">

    <div class="mr-sign-box">
      <div class="sign-display">
        {% if prepared_sig %}
          <img class="sign-img" src="{{ prepared_sig }}" alt="Prepared Signature">
        {% endif %}
      </div>
      <div class="sign-line">Prepared By</div>
      <div class="sign-name">{{ prepared_by_name }}</div>
      <div class="sign-note">Procurement / Store</div>
    </div>

    <div class="mr-stamp-box">
      <div class="stamp-display">
        {% if common_stamp %}
          <img class="stamp-img" src="{{ common_stamp }}" alt="Stamp">
        {% endif %}
      </div>
    </div>

    <div class="mr-sign-box">
      <div class="sign-display">
        {% if approved_sig %}
          <img class="sign-img" src="{{ approved_sig }}" alt="Approved Signature">
        {% endif %}
      </div>
      <div class="sign-line">Approved By</div>
      <div class="sign-name">{{ approved_by_name }}</div>
      <div class="sign-note">Manager Signature & Stamp</div>
    </div>

  </div>

  <!--<div class="mr-contact">-->
  <!--  <div>-->
  <!--    <b>For inquiries:</b><br>-->
  <!--    Call / WhatsApp: +252 XX XXX XXXX<br>-->
  <!--    Email: info@yourcompany.com-->
  <!--  </div>-->
  <!--  <div style="text-align:right;">-->
  <!--    <b>Address:</b><br>-->
  <!--    Your Company Address Line 1<br>-->
  <!--    City, Country-->
  <!--  </div>-->
  <!--</div>-->
  {% endif %}
</div>
